package com.coraline.feast;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.gametest.*;
import com.coraline.otherworld.OtherWorld;
import com.coraline.registry.CharacterCast;

@GameTestHolder("coraline")
@PrefixGameTestTemplate(false)
public final class ShowRevisionGameTests {
    private static ServerPlayer player(GameTestHelper h,boolean activity){var l=h.getLevel().getServer().getLevel(activity?ActivityWorld.KEY:OtherWorld.KEY);var p=new ServerPlayer(l.getServer(),l,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"ShowRevisionQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(p.server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);var s=new VisitData.Scene();s.owner=p.getUUID();s.door=UUID.randomUUID();s.stage=VisitData.Stage.DONE;s.loop.phase=OtherMotherLoopState.Phase.EVENT_INTRO;s.loop.event.putInt("Serial",7);s.loop.event.putString("Type","THEATRE");s.loop.event.putBoolean("TheatrePending",true);var n=TheatreVisit.data(s);n.putUUID("Owner",s.owner);n.putInt("Serial",7);n.putString("Phase","TRAVEL");p.getPersistentData().putUUID("CoralineVisitDoor",s.door);VisitData.get(p.server).scenes.put(s.owner,s);return p;}
    private static void remove(ServerPlayer p){var s=OtherMotherLoop.scene(p);if(s!=null){ShowPlayerSafety.release(p,s);VisitData.get(p.server).scenes.remove(s.owner);}}
    @GameTest(template="empty") public static void theatreInvitationGatesAccessAndHud(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{h.assertFalse(VisitEvents.showDoor(p,"basement"),"Selection prematurely unlocked basement");var packet=new net.minecraft.nbt.CompoundTag();TheatreVisit.status(p,s,packet);h.assertFalse(packet.contains("ShowObjective"),"Premature basement objective");TheatreVisit.data(s).putBoolean("InvitationDone",true);h.assertTrue(VisitEvents.showDoor(p,"basement"),"Finished invitation failed to authorize basement");TheatreVisit.status(p,s,packet);h.assertTrue(packet.contains("ShowObjective"),"Missing invited objective");}finally{remove(p);}h.succeed();}
    @GameTest(template="empty") public static void fullSuspicionAndTrustQueueSameMilestoneEvenOnSkip(GameTestHelper h){var p=player(h,false);var s=OtherMotherLoop.scene(p);try{s.loop.trust=.99F;s.loop.suspicion=.99F;h.assertFalse(BlackIsTraditional.pending(s),"Premature milestone");s.loop.trust=1;h.assertTrue(BlackIsTraditional.pending(s),"Full trust ignored");s.loop.trust=0;s.loop.suspicion=1;h.assertTrue(BlackIsTraditional.pending(s),"Full suspicion ignored");int serial=s.loop.event.getInt("Serial");VisitEvents.next(p,s,true);h.assertTrue(s.loop.event.getInt("Serial")==serial,"Skip replaced blocked milestone with random event");BlackIsTraditional.data(s).putBoolean("Started",true);h.assertFalse(BlackIsTraditional.pending(s),"Milestone repeated");}finally{remove(p);}h.succeed();}
    @GameTest(template="empty") public static void namedGuestCanDuckThroughDoorWithoutChangingOtherActors(GameTestHelper h){var actor=CharacterCast.ENTITIES.get("other_bobinsky").get().create(h.getLevel());h.assertTrue(actor.getBbHeight()>3,"Expected tall canonical model");actor.partyDoorDuck(true);h.assertTrue(actor.getBbHeight()<=1.85F,"Tall guest cannot pass ordinary door");actor.partyDoorDuck(false);h.assertTrue(actor.getBbHeight()>3,"Guest dimensions not restored");actor.discard();h.succeed();}
    @GameTest(template="empty") public static void roseThrowAccountsForGravityAndDrag(GameTestHelper h){var target=new Vec3(20,2,0);var v=TheatreVisit.roseVelocity(Vec3.ZERO,target);var at=Vec3.ZERO;for(int i=0;i<32;i++){v=v.add(0,-.04,0);at=at.add(v);v=v.scale(.98);}h.assertTrue(at.distanceTo(target)<.01,"Rose falls short of the player");h.succeed();}
    @GameTest(template="empty") public static void circusMiceAreActuallyAdmittedByRealmProtection(GameTestHelper h){var p=player(h,true);var s=OtherMotherLoop.scene(p);var c=new BlockPos(79300,180,79300);var l=p.serverLevel();l.getChunkAt(c);p.setPos(Vec3.atBottomCenterOf(c));for(int x=(c.getX()-18)>>4;x<=(c.getX()+18)>>4;x++)for(int z=(c.getZ()-18)>>4;z<=(c.getZ()+18)>>4;z++)l.setChunkForced(x,z,true);h.runAfterDelay(30,()->MouseCircusChoreography.reveal(p,s,c));h.runAfterDelay(50,()->{try{int count=MouseCircusChoreography.count(p,s,c);h.assertTrue(count==48,"Expected 48 admitted jumping mice; found "+count);MouseCircusChoreography.reveal(p,s,c);h.assertTrue(MouseCircusChoreography.count(p,s,c)==48,"Repeated reveal cloned the mice");}finally{MouseCircusChoreography.cleanup(p,s,c);for(int x=(c.getX()-18)>>4;x<=(c.getX()+18)>>4;x++)for(int z=(c.getZ()-18)>>4;z<=(c.getZ()+18)>>4;z++)l.setChunkForced(x,z,false);remove(p);}h.succeed();});}
    @GameTest(template="empty") public static void stuntLeavesChairBehindAndReleasesItsOwnCarrier(GameTestHelper h){var p=player(h,true);var s=OtherMotherLoop.scene(p);var l=p.serverLevel();var at=TheatreSite.playerSeat(p,s);l.getChunkAt(at);p.setPos(Vec3.atBottomCenterOf(at));var chair=TheatreSite.ensure(p,s,l,CinematicPropEntity.SEAT,at,0);try{h.assertTrue(p.startRiding(chair,true),"Could not sit");TheatreVisit.data(s).putString("Phase","PERFORMING");h.assertTrue(ShowPlayerSafety.seatLocked(p),"Theatre seat is not locked");h.assertTrue(ShowPlayerSafety.attach(p,s,chair),"Stunt attachment failed");h.assertTrue(p.getVehicle()!=chair&&ShowPlayerSafety.active(p),"Stunt lifted the chair");var origin=chair.position();ShowPlayerSafety.move(p,s,new ScriptedShowTimeline.Point(0,10,-25,0,0));h.assertTrue(chair.position().equals(origin),"Chair followed airborne player");ShowPlayerSafety.release(p,s);h.assertTrue(p.getVehicle()==null&&!ShowPlayerSafety.active(p),"Stunt did not release");}finally{ShowPlayerSafety.release(p,s);chair.discard();remove(p);}h.succeed();}
}
